'use client'

import { useCallback, useEffect, useId, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { cn } from '@/lib/utils'
import { IconCheck, IconCopy } from '@tabler/icons-react'
import { focus } from './shared'
import { SelectChevron } from './speech-select'

export function CopyIcon({ copied }: { copied: boolean }) {
  return copied ? (
    <IconCheck aria-hidden="true" strokeWidth={1.5} className="size-4" />
  ) : (
    <IconCopy aria-hidden="true" strokeWidth={1.5} className="size-4" />
  )
}

export function ApiPromptInput({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  return (
    <span className="group relative flex h-6 min-w-0 flex-auto self-center rounded-lg bg-[#eef6ff]/70 ring-[.5px] ring-[#78b7ff] ring-inset transition hover:ring-[#368cff] focus-within:ring-1 focus-within:ring-[#368cff]">
      <input
        type="text"
        value={value}
        onChange={(event) => onChange(event.target.value)}
        placeholder=" "
        spellCheck={false}
        maxLength={500}
        aria-label="Prompt"
        className="h-6 w-full min-w-0 bg-transparent px-1.5 text-[#052f70] caret-[#368cff] outline-none"
      />
      <span className="pointer-events-none absolute inset-y-px left-px w-7 rounded-l-lg bg-gradient-to-r from-[#eef6ff] to-transparent opacity-0 transition-opacity group-focus-within:opacity-100" />
      <span className="pointer-events-none absolute inset-y-px right-px w-7 rounded-r-lg bg-gradient-to-l from-[#eef6ff] to-transparent opacity-0 transition-opacity group-focus-within:opacity-100" />
    </span>
  )
}

export function CodeLanguageSelect({
  value,
  onChange,
}: {
  value: 'ts' | 'python'
  onChange: (value: 'ts' | 'python') => void
}) {
  const [open, setOpen] = useState(false)
  const [menuPosition, setMenuPosition] = useState({ left: 0, top: 0 })
  const triggerRef = useRef<HTMLButtonElement>(null)
  const menuRef = useRef<HTMLDivElement>(null)
  const listboxId = useId()
  const options = [
    { id: 'ts', label: 'TypeScript' },
    { id: 'python', label: 'Python' },
  ] as const

  const updatePosition = useCallback(() => {
    const trigger = triggerRef.current
    if (!trigger) return
    const rect = trigger.getBoundingClientRect()
    setMenuPosition({ left: rect.left, top: rect.bottom - 2 })
  }, [])

  useEffect(() => {
    if (!open) return
    updatePosition()

    const closeOnOutsidePress = (event: MouseEvent) => {
      const target = event.target as Node
      if (!triggerRef.current?.contains(target) && !menuRef.current?.contains(target)) {
        setOpen(false)
      }
    }
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setOpen(false)
        triggerRef.current?.focus()
      }
    }

    document.addEventListener('mousedown', closeOnOutsidePress)
    document.addEventListener('keydown', closeOnEscape)
    window.addEventListener('resize', updatePosition)
    window.addEventListener('scroll', updatePosition, true)
    return () => {
      document.removeEventListener('mousedown', closeOnOutsidePress)
      document.removeEventListener('keydown', closeOnEscape)
      window.removeEventListener('resize', updatePosition)
      window.removeEventListener('scroll', updatePosition, true)
    }
  }, [open, updatePosition])

  const menu =
    open && typeof document !== 'undefined'
      ? createPortal(
          <div
            ref={menuRef}
            id={listboxId}
            role="listbox"
            aria-label="Code language"
            className="fixed z-[220] w-[138px] rounded-2xl bg-white p-1.5 text-[15px] leading-6 text-black shadow-[0_0_1px_rgba(0,0,0,.4),0_1px_1px_rgba(0,0,0,.04),0_8px_24px_rgba(0,0,0,.10)] ring-[.5px] ring-black/[.075] outline-none"
            style={menuPosition}
          >
            {options.map((option) => {
              const selected = option.id === value
              return (
                <button
                  key={option.id}
                  type="button"
                  role="option"
                  aria-selected={selected}
                  onClick={() => {
                    onChange(option.id)
                    setOpen(false)
                    triggerRef.current?.focus()
                  }}
                  className="flex h-9 w-full items-center rounded-[10px] px-2.5 text-left outline-none transition-colors hover:bg-[#f5f3f1] focus-visible:bg-[#f5f3f1]"
                >
                  <span className="min-w-0 flex-1 truncate">{option.label}</span>
                  {selected && <IconCheck aria-hidden="true" strokeWidth={1.5} className="size-4 flex-none" />}
                </button>
              )
            })}
          </div>,
          document.body,
        )
      : null

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        aria-label="Code language"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        onClick={() => {
          updatePosition()
          setOpen((current) => !current)
        }}
        className={cn(
          'flex h-9 items-center gap-2 rounded-xl pr-2 pl-3 text-[14px] leading-5 font-medium text-black outline-none transition-colors',
          focus,
        )}
      >
        <span>{value === 'ts' ? 'TypeScript' : 'Python'}</span>
        <span className="transition-transform">
          <SelectChevron />
        </span>
      </button>
      {menu}
    </>
  )
}

'use client'

import type { CSSProperties } from 'react'
import { cn } from '@/lib/utils'
import {
  IconChevronLeft,
  IconChevronRight,
  IconLoader2,
  IconPlayerPauseFilled,
  IconPlayerPlayFilled,
} from '@tabler/icons-react'
import { voices } from '../data'

export type OrbStyle = CSSProperties & {
  '--orb-x': string
  '--orb-mobile-x': string
  '--orb-scale': number
  '--orb-mobile-scale': number
}

export type VoiceDetailStyle = CSSProperties & {
  '--detail-x': string
}

export const focus =
  'focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#266df0]'
export const buttonShadow = 'shadow-[0_0_1px_rgb(0_0_0_/_0.4),0_1px_1px_rgb(0_0_0_/_0.04),0_2px_4px_rgb(0_0_0_/_0.04)]'

export function Chevron({ direction }: { direction: 'previous' | 'next' }) {
  return direction === 'previous' ? (
    <IconChevronLeft aria-hidden="true" strokeWidth={1.5} className="size-5" />
  ) : (
    <IconChevronRight aria-hidden="true" strokeWidth={1.5} className="size-5" />
  )
}

export function PlayIcon({ playing }: { playing: boolean }) {
  if (playing) {
    return <IconPlayerPauseFilled aria-hidden="true" className="size-5" />
  }

  return <IconPlayerPlayFilled aria-hidden="true" className="size-5" />
}

export function SpeechLoadingSpinner() {
  return (
    <IconLoader2
      aria-hidden="true"
      strokeWidth={2.25}
      className="size-4 animate-spin"
      style={{ animationDuration: '0.7s' }}
    />
  )
}

export function VoiceDetails({ voiceIndex, muted = false }: { voiceIndex: number; muted?: boolean }) {
  const voice = voices[voiceIndex]

  return (
    <div className="flex h-20 min-w-0 flex-col items-center justify-center gap-2 text-center">
      <span
        className={cn(
          'inline-flex items-center rounded-sm text-[16px] leading-6',
          muted ? 'text-[#777169]' : 'text-black',
        )}
      >
        {voice.category}
      </span>
      <p
        className={cn(
          'm-0 max-w-[216px] text-[13px] leading-[18px] text-balance',
          muted ? 'text-[#a9a49e]' : 'text-[#777169]',
        )}
      >
        {voice.description}
      </p>
    </div>
  )
}

export function CompactPlayButton({
  playing,
  loading = false,
  onClick,
  iconOnly = false,
}: {
  playing: boolean
  loading?: boolean
  onClick: () => void
  iconOnly?: boolean
}) {
  return (
    <button
      type="button"
      aria-label={playing ? 'Pause' : 'Play'}
      disabled={loading}
      onClick={onClick}
      className={cn(
        'flex flex-none items-center justify-center rounded-full bg-black text-white transition hover:bg-[#59544f] disabled:cursor-default',
        focus,
        iconOnly || loading ? 'size-9' : 'h-9 px-3.5 text-[15px] leading-none',
      )}
    >
      {loading ? (
        <SpeechLoadingSpinner />
      ) : iconOnly ? (
        <span className="[&>svg]:!size-4">
          <PlayIcon playing={playing} />
        </span>
      ) : playing ? (
        'Pause'
      ) : (
        'Play'
      )}
    </button>
  )
}

export function SectionDivider() {
  return (
    <div className="relative mx-auto h-1 max-w-[1304px] border-x border-black/[.075] bg-black/[.075]">
      <span className="absolute top-1/2 left-0 z-20 flex size-5 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-[#fdfcfc]">
        <i className="size-0.5 rounded-full bg-black" />
      </span>
      <span className="absolute top-1/2 right-0 z-20 flex size-5 translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-[#fdfcfc]">
        <i className="size-0.5 rounded-full bg-black" />
      </span>
    </div>
  )
}

'use client'

import { useCallback, useEffect, useId, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { cn } from '@/lib/utils'
import { IconCheck, IconChevronDown } from '@tabler/icons-react'
import { focus } from './shared'

export function SelectChevron() {
  return <IconChevronDown aria-hidden="true" strokeWidth={2} className="size-4 flex-none text-[#a9a49e]" />
}

export function InlineSelectChevron() {
  return <IconChevronDown aria-hidden="true" strokeWidth={1.5} className="ml-0.5 size-4 flex-none" />
}

export type SpeechSelectItem = {
  id: string
  label: string
  description?: string
  image: string
}

export function SpeechSelect({
  ariaLabel,
  value,
  items,
  onChange,
  menuWidth,
  hideTriggerImageOnMobile = false,
  hideTriggerLabelOnMobile = false,
  inlineCode = false,
  triggerValue,
}: {
  ariaLabel: string
  value: string
  items: readonly SpeechSelectItem[]
  onChange: (value: string) => void
  menuWidth: number
  hideTriggerImageOnMobile?: boolean
  hideTriggerLabelOnMobile?: boolean
  inlineCode?: boolean
  triggerValue?: string
}) {
  const [open, setOpen] = useState(false)
  const [menuPosition, setMenuPosition] = useState({ left: 0, top: 0 })
  const triggerRef = useRef<HTMLButtonElement>(null)
  const menuRef = useRef<HTMLDivElement>(null)
  const listboxId = useId()
  const selectedItem = items.find((item) => item.id === value) ?? items[0]

  const updateMenuPosition = useCallback(() => {
    const trigger = triggerRef.current
    if (!trigger) return
    const rect = trigger.getBoundingClientRect()
    const edge = 6
    setMenuPosition({
      left: Math.max(edge, Math.min(rect.left - 4, window.innerWidth - menuWidth - edge)),
      top: rect.bottom,
    })
  }, [menuWidth])

  const toggleMenu = () => {
    if (!open) updateMenuPosition()
    setOpen((current) => !current)
  }

  useEffect(() => {
    if (!open) return

    const closeFromOutside = (event: PointerEvent) => {
      const target = event.target as Node
      if (!triggerRef.current?.contains(target) && !menuRef.current?.contains(target)) {
        setOpen(false)
      }
    }
    const closeFromEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setOpen(false)
        triggerRef.current?.focus()
      }
    }
    const reposition = () => updateMenuPosition()

    document.addEventListener('pointerdown', closeFromOutside)
    document.addEventListener('keydown', closeFromEscape)
    window.addEventListener('resize', reposition)
    window.addEventListener('scroll', reposition, true)

    const selectedOption = menuRef.current?.querySelector<HTMLElement>('[role="option"][aria-selected="true"]')
    selectedOption?.scrollIntoView({ block: 'nearest' })

    return () => {
      document.removeEventListener('pointerdown', closeFromOutside)
      document.removeEventListener('keydown', closeFromEscape)
      window.removeEventListener('resize', reposition)
      window.removeEventListener('scroll', reposition, true)
    }
  }, [open, updateMenuPosition])

  const menu = open
    ? createPortal(
        <div
          ref={menuRef}
          id={listboxId}
          role="listbox"
          aria-label={ariaLabel}
          className="fixed z-[220] max-h-[206px] overflow-auto rounded-2xl bg-white p-1.5 text-[15px] leading-[22px] text-black outline-none [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          style={{
            left: menuPosition.left,
            top: menuPosition.top,
            width: menuWidth,
            boxShadow: 'rgba(0, 0, 0, 0.4) 0px 0px 1px 0px, rgba(0, 0, 0, 0.04) 0px 4px 4px 0px',
          }}
          onKeyDown={(event) => {
            if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
            event.preventDefault()
            const options = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="option"]'))
            const current = options.indexOf(document.activeElement as HTMLButtonElement)
            const direction = event.key === 'ArrowDown' ? 1 : -1
            const next =
              current === -1
                ? options.findIndex((option) => option.getAttribute('aria-selected') === 'true')
                : (current + direction + options.length) % options.length
            options[Math.max(0, next)]?.focus()
          }}
        >
          {items.map((item) => {
            const selected = item.id === value
            return (
              <button
                key={item.id}
                type="button"
                role="option"
                aria-selected={selected}
                onClick={() => {
                  onChange(item.id)
                  setOpen(false)
                  triggerRef.current?.focus()
                }}
                className={cn(
                  'relative flex h-9 w-full items-center gap-2 rounded-xl pl-2.5 text-left outline-none transition-colors before:pointer-events-none before:absolute before:inset-0 before:rounded-xl before:bg-[#f5f3f1] before:opacity-0 before:transition-opacity hover:before:opacity-100 focus-visible:before:opacity-100',
                  selected ? 'pr-1.5' : 'pr-[38px]',
                )}
              >
                <span
                  aria-hidden="true"
                  className="relative z-10 size-4 flex-none self-center rounded-full bg-[#dedbd8] bg-cover bg-center"
                  style={{ backgroundImage: `url("${item.image}")` }}
                />
                <span className="relative z-10 min-w-0 truncate">{item.label}</span>
                {item.description ? (
                  <span className="relative z-10 ml-1 flex-none text-[13px] leading-[18px] text-[#777169]">
                    {item.description}
                  </span>
                ) : null}
                {selected ? (
                  <IconCheck
                    aria-hidden="true"
                    strokeWidth={1.5}
                    className="relative z-10 ml-auto size-6 flex-none text-black"
                  />
                ) : null}
              </button>
            )
          })}
        </div>,
        document.body,
      )
    : null

  return (
    <span className={inlineCode ? 'inline' : 'block min-w-0'}>
      <button
        ref={triggerRef}
        type="button"
        aria-label={ariaLabel}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        onClick={toggleMenu}
        className={
          inlineCode
            ? cn(
                'inline-flex h-[23px] max-w-[230px] items-center rounded-lg bg-[#eef6ff]/70 pr-[3px] pl-1 align-middle text-[13px] leading-none font-normal text-[#052f70] ring-[.5px] ring-[#78b7ff] ring-inset outline-none transition hover:ring-1 hover:ring-[#368cff]',
                focus,
              )
            : cn(
                'flex h-9 w-full items-center gap-2 rounded-xl pr-2 pl-3 text-[15px] leading-[22px] font-medium text-black outline-none transition-colors',
                focus,
              )
        }
      >
        <span className={cn('flex min-w-0 flex-1 items-baseline', !inlineCode && 'gap-2')}>
          {!inlineCode && (
            <span
              aria-hidden="true"
              className={cn(
                'size-4 flex-none self-center rounded-full bg-[#dedbd8] bg-cover bg-center',
                hideTriggerImageOnMobile && 'max-sm:hidden',
              )}
              style={{ backgroundImage: `url("${selectedItem.image}")` }}
            />
          )}
          <span className={cn('min-w-0 truncate', hideTriggerLabelOnMobile && 'max-sm:hidden')}>
            {triggerValue ?? selectedItem.label}
          </span>
        </span>
        {inlineCode ? (
          <InlineSelectChevron />
        ) : (
          <span className="flex-none transition-transform">
            <SelectChevron />
          </span>
        )}
      </button>
      {menu}
    </span>
  )
}

