  const [voiceId, setVoiceId] = useState<string>(speechVoices[0].id)
  const [codeLanguage, setCodeLanguage] = useState<'ts' | 'python'>('ts')
  const [prompt, setPrompt] = useState(speechInitialText)
  const [copied, setCopied] = useState(false)
  const [playing, setPlaying] = useState(false)
  const [loading, setLoading] = useState(false)
  const audioRef = useRef<HTMLAudioElement>(null)
  const selectedVoice = speechVoices.find((voice) => voice.id === voiceId) ?? speechVoices[0]
  const code =
    codeLanguage === 'ts'
      ? `import { ElevenLabsClient } from "@elevenlabs/elevenlabs-js";

const elevenlabs = new ElevenLabsClient();
const audio = await elevenlabs
  .textToSpeech.convert("${voiceId}", {
    text: "${prompt}",
    modelId: "eleven_v3",
    languageCode: "${language}",
  });`
      : `from elevenlabs.client import ElevenLabs

elevenlabs = ElevenLabs()
audio = elevenlabs.text_to_speech.convert(
  voice_id="${voiceId}",
  text="${prompt}",
  model_id="eleven_v3",
  language_code="${language}",
)`

  const copyCode = async () => {
    try {
      await navigator.clipboard.writeText(code)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1400)
    } catch {
      setCopied(false)
    }
  }

  const runCode = () => {
    const audio = audioRef.current
    if (!audio || loading) return
    if (audio.paused) {
      setLoading(true)
      void audio
        .play()
        .then(() => {
          setLoading(false)
          setPlaying(true)
        })
        .catch(() => {
          setLoading(false)
          setPlaying(false)
        })
    } else {
      audio.pause()
      setLoading(false)
      setPlaying(false)
    }
  }

  return (
    <div className="absolute top-[68px] left-1/2 z-[5] flex h-80 w-[calc(100%-32px)] max-w-[640px] -translate-x-1/2 flex-col overflow-hidden rounded-3xl bg-white shadow-[inset_0_0_0_.5px_rgb(0_0_0_/_0.075)] md:top-[69px]">
      <div className="min-h-0 flex-1 overflow-auto px-5 pt-4 [font-family:var(--font-geist-mono),monospace] text-[12px] leading-[21px] text-black [scrollbar-width:none] sm:text-[13px] sm:leading-[26px]">
        {codeLanguage === 'ts' ? (
          <>
            <p className="mb-[26px]">
              <span className="text-[#f41a2f]">import</span> {'{ ElevenLabsClient } '}
              <span className="text-[#f41a2f]">from</span>{' '}
              <span className="text-[#052f70]">&quot;@elevenlabs/elevenlabs-js&quot;</span>;
            </p>
            <p>
              <span className="text-[#f41a2f]">const</span> <span className="text-[#0a59d2]">elevenlabs</span> = new
              ElevenLabsClient();
            </p>
            <p>
              <span className="text-[#f41a2f]">const</span> <span className="text-[#0a59d2]">audio</span> ={' '}
              <span className="text-[#f41a2f]">await</span> elevenlabs
            </p>
            <p className="pl-4">
              .textToSpeech.convert(&quot;
              <SpeechSelect
                ariaLabel="Voice"
                value={voiceId}
                items={speechVoices}
                onChange={setVoiceId}
                menuWidth={304}
                inlineCode
                triggerValue={voiceId}
              />
              &quot;, {'{'}
            </p>
            <p className="flex min-w-0 items-center pl-8">
              <span className="whitespace-pre text-[#0a59d2]">text:</span>
              <span className="whitespace-pre"> &quot;</span>
              <ApiPromptInput value={prompt} onChange={setPrompt} />
              <span className="whitespace-pre">&quot;,</span>
            </p>
            <p className="pl-8">
              <span className="text-[#0a59d2]">modelId:</span>{' '}
              <span className="text-[#052f70]">&quot;eleven_v3&quot;</span>,
            </p>
            <p className="pl-8">
              <span className="text-[#0a59d2]">languageCode:</span> &quot;
              <SpeechSelect
                ariaLabel="Language"
                value={language}
                items={speechLanguageItems}
                onChange={setLanguage}
                menuWidth={222}
                inlineCode
                triggerValue={language}
              />
              &quot;,
            </p>
            <p className="pl-4">{'});'}</p>
          </>
        ) : (
          <>
            <p className="mb-[26px]">
              <span className="text-[#f41a2f]">from</span> elevenlabs.client{' '}
              <span className="text-[#f41a2f]">import</span> ElevenLabs
            </p>
            <p>elevenlabs = ElevenLabs()</p>
            <p>audio = elevenlabs.text_to_speech.convert(</p>
            <p className="pl-4">
              voice_id=&quot;
              <SpeechSelect
                ariaLabel="Voice"
                value={voiceId}
                items={speechVoices}
                onChange={setVoiceId}
                menuWidth={304}
                inlineCode
                triggerValue={voiceId}
              />
              &quot;,
            </p>
            <p className="flex min-w-0 items-center pl-4">
              <span className="whitespace-pre">text=&quot;</span>
              <ApiPromptInput value={prompt} onChange={setPrompt} />
              <span className="whitespace-pre">&quot;,</span>
            </p>
            <p className="pl-4">model_id=&quot;eleven_v3&quot;,</p>
            <p className="pl-4">
              language_code=&quot;
              <SpeechSelect
                ariaLabel="Language"
                value={language}
                items={speechLanguageItems}
                onChange={setLanguage}
                menuWidth={222}
                inlineCode
                triggerValue={language}
              />
              &quot;,
            </p>
            <p>)</p>
          </>
        )}
      </div>

      <div className="flex h-12 flex-none items-center gap-1 px-3 pb-3">
        <button
          type="button"
          aria-label={copied ? 'Copied' : 'Copy code'}
          onClick={copyCode}
          className={cn(
            'flex size-9 flex-none items-center justify-center rounded-full text-[#59544f] transition hover:text-black',
            focus,
          )}
        >
          <CopyIcon copied={copied} />
        </button>
        <CodeLanguageSelect value={codeLanguage} onChange={setCodeLanguage} />
        <button
          type="button"
          onClick={runCode}
          disabled={loading}
          className={cn(
            'ml-auto flex h-9 items-center justify-center rounded-full bg-black px-3.5 text-[14px] leading-none text-white transition hover:bg-[#59544f] disabled:cursor-default',
            focus,
          )}
        >
          {loading ? (
            <SpeechLoadingSpinner />
          ) : playing ? (
            'Pause'
          ) : (
            <>
              <span className="sm:hidden">Run</span>
              <span className="hidden sm:contents">Run code</span>
            </>
          )}
        </button>
      </div>
      <audio
        ref={audioRef}
        src={selectedVoice.preview}
        preload="none"
        className="hidden"
        onPlaying={() => {
          setLoading(false)
          setPlaying(true)
        }}
        onWaiting={() => setLoading(true)}
        onPause={() => {
          setLoading(false)
          setPlaying(false)
        }}
        onEnded={() => {
          setLoading(false)
          setPlaying(false)
        }}
      />
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import { IconCheck } from '@tabler/icons-react'
import { Chevron, CompactPlayButton, PlayIcon, focus } from '../../../components/shared'
import { speechInitialText, speechVoices } from '../../../data'
import { speechLanguageItems } from '../../../data/flags'
import { SpeechSelect } from '../../../components/speech-select'

export function CreativeTextToSpeechDemo() {
  const [speechText, setSpeechText] = useState(speechInitialText)
  const [language, setLanguage] = useState('en')
  const [voiceId, setVoiceId] = useState<string>(speechVoices[0].id)
  const [voicePage, setVoicePage] = useState(0)
  const [playing, setPlaying] = useState(false)
  const [loading, setLoading] = useState(false)
  const [playAfterVoiceSelection, setPlayAfterVoiceSelection] = useState(false)
  const audioRef = useRef<HTMLAudioElement>(null)
  const selectedVoice = speechVoices.find((voice) => voice.id === voiceId) ?? speechVoices[0]
  const visibleVoices = speechVoices.slice(voicePage * 5, voicePage * 5 + 5)
  const lastVoicePage = Math.ceil(speechVoices.length / 5) - 1
  const highlightedText = speechText.split(/(\[[^\]]+\])/g)

  useEffect(() => {
    const audio = audioRef.current
    if (!audio || !playAfterVoiceSelection) return

    setPlayAfterVoiceSelection(false)
    setLoading(true)
    void audio
      .play()
      .then(() => {
        setLoading(false)
        setPlaying(true)
      })
      .catch(() => {
        setLoading(false)
        setPlaying(false)
      })
  }, [playAfterVoiceSelection, voiceId])

  const toggle = () => {
    const audio = audioRef.current
    if (!audio || loading) return
    if (audio.paused) {
      setLoading(true)
      void audio
        .play()
        .then(() => {
          setLoading(false)
          setPlaying(true)
        })
        .catch(() => {
          setLoading(false)
          setPlaying(false)
        })
    } else {
      audio.pause()
      setLoading(false)
      setPlaying(false)
    }
  }

  return (
    <div className="absolute top-[68px] left-1/2 z-[5] flex h-80 w-[calc(100%-32px)] max-w-[832px] -translate-x-1/2 overflow-hidden rounded-3xl bg-white shadow-[inset_0_0_0_.5px_rgb(0_0_0_/_0.075)] md:top-[69px]">
      <div className="hidden w-1/2 flex-col border-r border-black/[.075] md:flex">
        <div className="h-[272px] overflow-hidden">
          {visibleVoices.map((voice, index) => {
            const selected = voice.id === voiceId
            const edgeSpacing =
              index === 0 ? 'h-[59px] pt-[11px]' : index === visibleVoices.length - 1 ? 'h-[59px] pb-[11px]' : 'h-12'
            return (
              <button
                key={voice.id}
                type="button"
                onClick={() => {
                  if (selected) {
                    toggle()
                    return
                  }
                  audioRef.current?.pause()
                  setPlaying(false)
                  setLoading(false)
                  setVoiceId(voice.id)
                  setPlayAfterVoiceSelection(true)
                }}
                aria-label={selected ? `${playing ? 'Pause' : 'Play'} ${voice.label}` : `Play ${voice.label} preview`}
                className={cn('group block w-full px-3 text-left', edgeSpacing, focus)}
              >
                <span
                  className={cn(
                    'flex h-12 w-full items-center gap-2.5 rounded-xl pr-4 pl-3 transition-colors hover:bg-[#f5f3f1]',
                    selected && 'bg-[#f5f3f1]',
                  )}
                >
                  <span className="relative size-5 flex-none">
                    <img src={voice.image} alt="" className="size-full rounded-full object-cover" />
                    {selected && (
                      <span className="absolute -top-1 -right-1 flex size-3 items-center justify-center rounded-full bg-black text-white ring-2 ring-[#f5f3f1]">
                        <IconCheck className="size-2 text-white" strokeWidth={2.5} aria-hidden="true" />
                      </span>
                    )}
                  </span>
                  <span className="flex min-w-0 flex-1 items-center justify-between gap-3">
                    <span className="truncate text-[15px] leading-5 font-medium text-black">{voice.label}</span>
                    <span
                      className={cn(
                        'truncate text-[14px] leading-5 font-medium text-[#777169]',
                        selected ? 'hidden' : 'group-hover:hidden',
                      )}
                    >
                      {voice.description}
                    </span>
                    <span
                      className={cn(
                        'ml-auto size-9 flex-none items-center justify-center rounded-full bg-white text-black shadow-[0_0_1px_rgb(0_0_0_/_0.34),0_1px_2px_rgb(0_0_0_/_0.04),0_2px_4px_rgb(0_0_0_/_0.04)] [&>svg]:!size-4',
                        selected ? 'flex' : 'hidden group-hover:flex',
                      )}
                    >
                      <PlayIcon playing={selected && playing} />
                    </span>
                  </span>
                </span>
              </button>
            )
          })}
        </div>
        <div className="flex h-12 items-center justify-between px-4">
          <button
            type="button"
            className={cn(
              'inline-flex h-9 items-center rounded-full bg-white px-3.5 text-[14px] leading-5 text-black shadow-[0_0_1px_rgb(0_0_0_/_0.34),0_1px_2px_rgb(0_0_0_/_0.04),0_2px_4px_rgb(0_0_0_/_0.04)] transition hover:bg-[#fbfaf9]',
              focus,
            )}
          >
            Explore 10,000+ voices
          </button>
          <div className="flex items-center text-[#59544f]">
            <button
              type="button"
              aria-label="Previous voices"
              disabled={voicePage === 0}
              onClick={() => setVoicePage((current) => Math.max(0, current - 1))}
              className={cn(
                'flex size-8 items-center justify-center rounded-full disabled:opacity-30 [&>svg]:size-4',
                focus,
              )}
            >
              <Chevron direction="previous" />
            </button>
            <button
              type="button"
              aria-label="Next voices"
              disabled={voicePage === lastVoicePage}
              onClick={() => setVoicePage((current) => Math.min(lastVoicePage, current + 1))}
              className={cn(
                'flex size-8 items-center justify-center rounded-full disabled:opacity-30 [&>svg]:size-4',
                focus,
              )}
            >
              <Chevron direction="next" />
            </button>
          </div>
        </div>
      </div>

      <div className="flex min-w-0 flex-1 flex-col">
        <div className="flex h-[272px] flex-col overflow-y-auto [scrollbar-width:none]">
          <div className="pointer-events-none z-10 -mb-3 hidden h-11 flex-none items-end px-5 pb-3 md:flex">
            <label htmlFor="creative-tts-text" className="truncate text-[12px] leading-[21px] text-[#a9a49e]">
              Enter your own text
            </label>
          </div>
          <div className="relative min-h-0 flex-1">
            <div
              aria-hidden="true"
              className="absolute inset-0 overflow-hidden px-5 pt-3 text-[16px] leading-6 text-black whitespace-pre-wrap"
            >
              {highlightedText.map((part, index) =>
                part.startsWith('[') ? (
                  <span key={`${part}-${index}`} className="text-[#a9a49e]">
                    {part}
                  </span>
                ) : (
                  part
                ),
              )}
            </div>
            <textarea
              id="creative-tts-text"
              value={speechText}
              onChange={(event) => setSpeechText(event.target.value)}
              aria-label="Enter your own text"
              spellCheck={false}
              className={cn(
                'absolute inset-0 size-full resize-none overflow-hidden bg-transparent px-5 pt-3 text-[16px] leading-6 text-transparent caret-black outline-none',
                focus,
              )}
            />
            <div className="pointer-events-none absolute right-0 bottom-0 left-0 h-6 bg-gradient-to-t from-white" />
          </div>
        </div>
        <div className="flex h-12 items-start gap-1 px-3 pb-3">
          <SpeechSelect
            ariaLabel="Language"
            value={language}
            items={speechLanguageItems}
            onChange={setLanguage}
            menuWidth={214}
          />
          <div className="ml-auto">
            <CompactPlayButton playing={playing} loading={loading} onClick={toggle} />
          </div>
        </div>
      </div>

      <audio
        ref={audioRef}
        src={selectedVoice.preview}
        preload="none"
        className="hidden"
        onPlaying={() => {
          setLoading(false)
          setPlaying(true)
        }}
        onWaiting={() => setLoading(true)}
        onPause={() => {
          setLoading(false)
          setPlaying(false)
        }}
        onEnded={() => {
          setLoading(false)
          setPlaying(false)
        }}
      />
    </div>
  )
}

'use client'

import type { CSSProperties } from 'react'
import { useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import { OrbSmooth } from '@/components/orb/smooth/index'
import { voices } from '../../../data'
import { Chevron, PlayIcon, VoiceDetails, focus, buttonShadow } from '../../../components/shared'

export function VoiceGeneratorDemo() {
  const [activeVoice, setActiveVoice] = useState(5)
  const [isPlaying, setIsPlaying] = useState(false)
  const [playAfterSelection, setPlayAfterSelection] = useState(false)
  const [orbTextureReady, setOrbTextureReady] = useState<string | null>(null)
  const audioRef = useRef<HTMLAudioElement>(null)

  const selectVoice = (index: number) => {
    const audio = audioRef.current

    if (index !== activeVoice) {
      audio?.pause()
      setIsPlaying(false)
      setActiveVoice(index)
      setPlayAfterSelection(true)
      return
    }

    if (!audio) return
    if (audio.paused) {
      void audio.play().then(() => setIsPlaying(true))
    } else {
      audio.pause()
      setIsPlaying(false)
    }
  }

  const moveVoice = (direction: -1 | 1) => {
    const next = Math.min(voices.length - 1, Math.max(0, activeVoice + direction))
    if (next === activeVoice) return

    audioRef.current?.pause()
    setIsPlaying(false)
    setActiveVoice(next)
  }

  return (
    <>
      <div className="absolute inset-0 z-[2] overflow-hidden">
        {voices.map((voice, index) => {
          const offset = index - activeVoice
          const distance = Math.abs(offset)
          const direction = Math.sign(offset)

          const desktopX =
            distance === 0 ? 0 : direction * (distance === 1 ? 310 : distance === 2 ? 534 : 534 + (distance - 2) * 220)
          const mobileX =
            distance === 0 ? 0 : direction * (distance === 1 ? 200 : distance === 2 ? 292 : 292 + (distance - 2) * 120)

          const desktopScale = distance === 0 ? 1 : distance === 1 ? 0.787 : distance === 2 ? 0.567 : 0.4
          const mobileScale = distance === 0 ? 1 : distance === 1 ? 0.7 : distance === 2 ? 0.5 : 0.35
          const opacity = distance === 0 ? 1 : distance === 1 ? 0.96 : distance === 2 ? 0.72 : 0

          const orbStyle = {
            '--orb-x': `${desktopX}px`,
            '--orb-mobile-x': `${mobileX}px`,
            '--orb-scale': desktopScale,
            '--orb-mobile-scale': mobileScale,
            opacity,
            zIndex: Math.max(0, 3 - distance),
            pointerEvents: distance <= 2 ? 'auto' : 'none',
          } as CSSProperties

          return (
            <div
              key={voice.name}
              style={orbStyle}
              className="group absolute top-[127px] left-1/2 size-[200px] origin-center [transform:translate3d(calc(-50%+var(--orb-mobile-x)),0,0)_scale(var(--orb-mobile-scale))] will-change-[transform,opacity] transition-[transform,opacity] duration-700 ease-[cubic-bezier(.22,1,.36,1)] lg:top-[65px] lg:size-64 lg:[transform:translate3d(calc(-50%+var(--orb-x)),0,0)_scale(var(--orb-scale))]"
            >
              <button
                type="button"
                aria-label={`${isPlaying && distance === 0 ? 'Pause' : 'Play'} ${voice.name} preview`}
                onClick={() => selectVoice(index)}
                className={cn('absolute inset-0 z-30 cursor-pointer rounded-full', focus)}
              />
              <span className="pointer-events-none absolute -inset-1 scale-[.985] rounded-full border-4 border-[#ebe8e4] opacity-0 transition group-hover:scale-100 group-hover:opacity-100" />
              <span className="absolute inset-0 overflow-hidden rounded-full">
                <img src={voice.image} alt="" className="size-full object-cover" />
              </span>
              {distance === 0 && (
                <div
                  aria-hidden="true"
                  className={cn(
                    'pointer-events-none absolute inset-0 z-10 overflow-hidden rounded-full transition-opacity duration-500',
                    isPlaying ? 'opacity-100' : 'opacity-0',
                  )}
                >
                  <OrbSmooth
                    textureUrl={voice.image}
                    audioMode={isPlaying ? 'file' : 'ambient'}
                    audioElement={audioRef}
                    audioSrc={voice.preview}
                    sphereScale={0.9}
                    spherePower={1.1}
                    grainOpacity={0.42}
                    animated
                    onTextureReady={setOrbTextureReady}
                    size={256}
                    className="size-full"
                  />
                </div>
              )}
              {distance === 0 && (
                <span
                  aria-hidden="true"
                  className={cn(
                    'pointer-events-none absolute top-1/2 left-1/2 z-20 inline-flex size-14 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-white text-black',
                    buttonShadow,
                  )}
                >
                  <PlayIcon playing={isPlaying} />
                </span>
              )}
            </div>
          )
        })}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 left-0 z-10 hidden w-44 bg-gradient-to-r from-[#f5f3f1] to-transparent md:block"
        />
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 right-0 z-10 hidden w-44 bg-gradient-to-l from-[#f5f3f1] to-transparent md:block"
        />
      </div>

      <div className="absolute top-[351px] right-4 left-4 z-[6] grid h-20 grid-cols-[44px_minmax(0,1fr)_44px] items-center gap-x-2 lg:hidden">
        <button
          type="button"
          aria-label="Previous voice"
          disabled={activeVoice === 0}
          onClick={() => moveVoice(-1)}
          className={cn(
            'inline-flex h-10 w-11 items-center justify-center rounded-full text-[#59544f] disabled:pointer-events-none disabled:opacity-0',
            focus,
          )}
        >
          <Chevron direction="previous" />
        </button>
        <div className="relative h-20 min-w-0 overflow-hidden">
          {voices.map((voice, index) => {
            const offset = index - activeVoice
            const distance = Math.abs(offset)
            const detailStyle = {
              '--detail-x': `${offset * 100}%`,
              opacity: distance === 0 ? 1 : 0,
              pointerEvents: distance === 0 ? 'auto' : 'none',
            } as CSSProperties

            return (
              <div
                key={voice.name}
                style={detailStyle}
                className="absolute top-0 left-1/2 h-20 w-full [transform:translate3d(calc(-50%+var(--detail-x)),0,0)] will-change-[transform,opacity] transition-[transform,opacity] duration-700 ease-[cubic-bezier(.22,1,.36,1)]"
              >
                <VoiceDetails voiceIndex={index} muted={distance !== 0} />
              </div>
            )
          })}
        </div>
        <button
          type="button"
          aria-label="Next voice"
          disabled={activeVoice === voices.length - 1}
          onClick={() => moveVoice(1)}
          className={cn(
            'inline-flex h-10 w-11 items-center justify-center rounded-full text-[#59544f] disabled:pointer-events-none disabled:opacity-0',
            focus,
          )}
        >
          <Chevron direction="next" />
        </button>
      </div>

      <div className="absolute top-[353px] left-1/2 z-[6] hidden h-20 w-[854px] -translate-x-1/2 overflow-hidden lg:block">
        {voices.map((voice, index) => {
          const offset = index - activeVoice
          const distance = Math.abs(offset)
          const detailStyle = {
            '--detail-x': `${offset * 309}px`,
            opacity: distance <= 1 ? 1 : 0,
            pointerEvents: distance === 0 ? 'auto' : 'none',
          } as CSSProperties

          return (
            <div
              key={voice.name}
              style={detailStyle}
              className="absolute top-0 left-1/2 h-20 w-[236px] px-4 [transform:translate3d(calc(-50%+var(--detail-x)),0,0)] will-change-[transform,opacity] transition-[transform,opacity] duration-700 ease-[cubic-bezier(.22,1,.36,1)]"
            >
              <VoiceDetails voiceIndex={index} muted={distance !== 0} />
            </div>
          )
        })}

        <button
          type="button"
          aria-label="Previous voice"
          disabled={activeVoice === 0}
          onClick={() => moveVoice(-1)}
          className={cn(
            'absolute top-5 left-[247.5px] inline-flex h-10 w-[50px] items-center justify-center rounded-full text-[#59544f] disabled:pointer-events-none disabled:opacity-0',
            focus,
          )}
        >
          <Chevron direction="previous" />
        </button>
        <button
          type="button"
          aria-label="Next voice"
          disabled={activeVoice === voices.length - 1}
          onClick={() => moveVoice(1)}
          className={cn(
            'absolute top-5 left-[556.5px] inline-flex h-10 w-[50px] items-center justify-center rounded-full text-[#59544f] disabled:pointer-events-none disabled:opacity-0',
            focus,
          )}
        >
          <Chevron direction="next" />
        </button>
      </div>

      <button
        type="button"
        className={cn(
          'absolute bottom-5 left-1/2 z-20 inline-flex h-10 -translate-x-1/2 items-center justify-center rounded-full bg-black px-4 text-[15px] leading-[22px] whitespace-nowrap text-white transition hover:bg-[#393735] active:scale-[.98] lg:right-8 lg:bottom-6 lg:left-auto lg:translate-x-0',
          focus,
        )}
      >
        Sign up
      </button>

      <audio
        ref={audioRef}
        src={voices[activeVoice].preview}
        crossOrigin="anonymous"
        preload="none"
        className="hidden"
        onEnded={() => setIsPlaying(false)}
      />
    </>
  )
}

